// A continuous, looping row of client marks, faded to white at both
// edges. Two identical halves back to back + a CSS animation translating
// by exactly -50% is what makes the loop seamless: as the first half
// slides fully out of view, the second half (an exact copy) is sitting
// exactly where the first one started.
//
// Every logo takes a `uid` (its render index within the doubled list) so
// any `<defs>` ids it owns (patterns, clip paths, the embedded image) stay
// unique across the two duplicated halves -- duplicate SVG ids on the same
// page are unreliable once more than one instance references them.

const Logo1 = ({ className, uid }) => (
  <svg
    width="300"
    height="200"
    viewBox="0 0 300 200"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className={className}
  >
    <g clipPath={`url(#logo1-clip-${uid})`}>
      <path d="M300 57H0V143H300V57Z" fill={`url(#logo1-pattern-${uid})`} />
    </g>
    <defs>
      <pattern
        id={`logo1-pattern-${uid}`}
        patternContentUnits="objectBoundingBox"
        width="1"
        height="1"
      >
        <use xlinkHref={`#logo1-image-${uid}`} transform="matrix(0.00169205 0 0 0.00588538 0 -0.00320018)" />
      </pattern>
      <clipPath id={`logo1-clip-${uid}`}>
        <rect width="300" height="86" fill="white" transform="translate(0 57)" />
      </clipPath>
      <image
        id={`logo1-image-${uid}`}
        width="591"
        height="171"
        preserveAspectRatio="none"
        xlinkHref="data:image/png;base64,"
      />
    </defs>
  </svg>
);

