// One entry per client mark. `Comp` renders it; `uid`-dependent logos
// (Logo1's embedded image, Logo3's clip path) get a unique id per render
// via the `uid` prop below -- the others just ignore that prop.
const BUILTIN_LOGOS = [Logo1, Logo2, Logo3, Logo4, Logo5, Logo6];

// A single uploaded logo (plain <img>, no `uid` needed -- there's no
// embedded SVG id to dedupe across the doubled strip).
const UploadedLogo = ({ src, alt, className }) => (
  // eslint-disable-next-line @next/next/no-img-element
  <img src={src} alt={alt || ""} className={className} />
);

// `logos` -- an array of { url, alt? } from the Info admin panel. When
// it's empty (nothing uploaded yet) the strip falls back to the six
// built-in marks above, so the page never ships an empty gap.
const LogoMarquee = ({ logos }) => {
  const custom = (logos ?? []).filter((l) => l?.url);
  const items = custom.length
    ? custom.map((l) => (props) => <UploadedLogo {...props} src={l.url} alt={l.alt} />)
    : BUILTIN_LOGOS;
  const doubled = [...items, ...items];

  return (
    <div className="relative w-full max-w-[380px] md:max-w-[460px] overflow-hidden">
      <div className="pointer-events-none absolute inset-y-0 left-0 w-12 md:w-16 z-10 bg-gradient-to-r from-white to-transparent" />
      <div className="pointer-events-none absolute inset-y-0 right-0 w-12 md:w-16 z-10 bg-gradient-to-l from-white to-transparent" />
      <div className="flex w-max items-center gap-20 animate-[tnf-marquee_32s_linear_infinite]">
        {doubled.map((Comp, i) => (
          <Comp key={i} uid={i} className="h-7 md:h-9 w-auto shrink-0 opacity-60 object-contain" />
        ))}
      </div>
    </div>
  );
};

export default LogoMarquee;
